import 'package:flutter/material.dart';
import '../services/cloud_service.dart';
import 'station_detail_screen.dart';
class StationSearchScreen extends StatefulWidget{const StationSearchScreen({super.key});@override State<StationSearchScreen> createState()=>_StationSearchScreenState();}
class _StationSearchScreenState extends State<StationSearchScreen>{final q=TextEditingController();final cloud=CloudService();List<Map<String,dynamic>> rows=[];bool busy=false;String? error;Future<void> search()async{setState(()=>busy=true);try{final r=await cloud.searchStations(q.text);if(mounted)setState(()=>rows=r);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Tra cứu trạm')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(controller:q,onSubmitted:(_)=>search(),decoration:InputDecoration(hintText:'Mã trạm, tên, địa chỉ, UPE, mã điện kế, KTV',prefixIcon:const Icon(Icons.search),suffixIcon:IconButton(onPressed:search,icon:const Icon(Icons.arrow_forward)),border:const OutlineInputBorder()))),if(busy)const LinearProgressIndicator(),if(error!=null)Padding(padding:const EdgeInsets.all(12),child:Text(error!,style:TextStyle(color:Theme.of(c).colorScheme.error))),Expanded(child:ListView.builder(itemCount:rows.length,itemBuilder:(_,i){final s=rows[i];return ListTile(leading:const CircleAvatar(child:Icon(Icons.cell_tower)),title:Text('${s['code']??''}  ${s['name']??''}'),subtitle:Text('${s['address']??''}\nUPE: ${s['upe']??'—'} • KTV: ${s['technician']??'—'}'),isThreeLine:true,onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>StationDetailScreen(code:s['code'].toString()))));}))]));}
